			ld sp, p_twice2
			jp ntc_xn
p_twice2_r:		; end of twice2
			ld sp, (p_twice2_rs)
			jp ntc_xn
p_corner_c:		; call corner (normal)
			pop hl			; g() descriptor
			ld de, pa_corner_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_corner_corner), hl
			ld (p_corner_rs), sp
			ld sp, p_corner
			jp ntc_xn
p_corner_r:		; end of corner
			ld sp, (p_corner_rs)
			jp ntc_xn
p_sum2_c:		; call sum2 (normal)
			pop hl			; g() descriptor
			ld de, pa_sum2_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_sum2_sum2), hl
			ld hl, 0
			ld (var_sum2_r), hl
			ld hl, 0
			ld (var_sum2_c), hl
			ld (p_sum2_rs), sp
			ld sp, p_sum2
			jp ntc_xn
p_sum2_r:		; end of sum2
			ld sp, (p_sum2_rs)
			jp ntc_xn
p_cols_c:		; call cols (normal)
			pop hl			; g() descriptor
			ld de, pa_cols_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_cols_cols), hl
			ld (p_cols_rs), sp
			ld sp, p_cols
			jp ntc_xn
p_cols_r:		; end of cols
			ld sp, (p_cols_rs)
			jp ntc_xn
p_clear2_c:		; call clear2 (normal)
			pop hl			; g() descriptor
			ld de, pa_clear2_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_clear2_r), hl
			ld hl, 0
			ld (var_clear2_c), hl
			ld (p_clear2_rs), sp
			ld sp, p_clear2
			jp ntc_xn
p_clear2_r:		; end of clear2
			ld sp, (p_clear2_rs)
			jp ntc_xn

